const $ = (id) => document.getElementById(id);
const state = { key: sessionStorage.getItem('zwf:key') || '', tenant: sessionStorage.getItem('zwf:tenant') || 'default', agents: [], commands: [] };
let dashboardRealtime = null;
let dashboardRealtimeLoad = null;
let dashboardRealtimeGeneration = 0;
let dashboardRefreshTimer = null;
let dashboardPollingTimer = null;
let dashboardSnapshotStale = false;
$('apiKey').value = state.key; $('tenantId').value = state.tenant;
function esc(value){return String(value ?? '').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function fmt(value,d=2){const n=Number(value||0);return Number.isFinite(n)?n.toLocaleString(undefined,{maximumFractionDigits:d}):'—';}
function age(iso){if(!iso)return '—';const s=Math.max(0,(Date.now()-Date.parse(iso))/1000);if(s<60)return `${Math.round(s)}s ago`;if(s<3600)return `${Math.round(s/60)}m ago`;if(s<86400)return `${Math.round(s/3600)}h ago`;return new Date(iso).toLocaleDateString();}
function banner(message=''){const el=$('errorBanner');el.textContent=message;el.classList.toggle('hidden',!message);}
async function api(path, options={}){const headers={'Accept':'application/json',...(options.headers||{})};if(state.key)headers['Authorization']=`Bearer ${state.key}`;if(state.tenant)headers['X-Tenant-ID']=state.tenant;if(options.body && typeof options.body!=='string'){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}const res=await fetch(path,{...options,headers});const text=await res.text();let data={};try{data=text?JSON.parse(text):{};}catch{data={error:{message:text||res.statusText}};}if(!res.ok)throw new Error(data?.error?.message||`HTTP ${res.status}`);return data;}
async function health(){try{await api('/health');$('healthDot').className='dot ok';$('healthText').textContent='Runtime healthy';}catch{$('healthDot').className='dot bad';$('healthText').textContent='Runtime unavailable';}}
async function refresh(){banner('');await health();if(!state.key){await refreshZarvisVoiceHealth();return;}try{const [o,a,t,p,r,m,c]=await Promise.all([api('/api/v1/overview'),api('/api/v1/agents'),api('/api/v1/tasks?limit=50'),api('/api/v1/providers'),api('/api/v1/recommendations'),api('/api/v1/memories?limit=10'),api('/api/v1/workspaces/commands').catch(()=>({items:[]}))]);state.agents=a.items||[];state.commands=(c.items||[]).filter(x=>x.available!==false);renderOverview(o);renderAgents(state.agents);renderTasks(t.items||[]);renderProviders(p.items||[],o.provider_mix||[]);renderMix(o.model_mix||[]);renderRecommendations(r.items||[]);renderMemories(m.items||[]);populateAgents();dashboardSnapshotStale=false;}catch(err){banner(err.message);dashboardSnapshotStale=true;dashboardRealtime?.markStale?.();}await refreshZarvisVoiceHealth();if(state.key)void zeazverseShow('overview');}
function renderOverview(o){$('mActive').textContent=fmt(o.active_tasks,0);$('mTasks').textContent=fmt(o.tasks_24h,0);$('mSuccess').textContent=`${fmt(o.success_rate)}% runtime success`;$('mOutcome').textContent=`${fmt(o.outcome_pass_rate)}%`;$('mCredits').textContent=fmt(o.credits_24h,4);$('mCostSuccess').textContent=`${fmt(o.cost_per_success,4)} / successful outcome`;$('mP95').textContent=`${fmt(o.p95_duration_seconds,1)}s`;$('mQueue').textContent=`${fmt(o.avg_queue_seconds,1)}s avg queue`;$('mDead').textContent=fmt(o.dead_letter_tasks,0);}
function populateAgents(){const select=$('agentSelect');const current=select.value;select.innerHTML=state.agents.filter(a=>a.enabled).map(a=>`<option value="${esc(a.id)}">${esc(a.name)} · ${esc(a.department)}</option>`).join('');if([...select.options].some(o=>o.value===current))select.value=current;}
function renderAgents(items){$('agentCards').innerHTML=items.map(a=>`<div class="agent"><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p><div class="agent-meta"><span>${esc(a.department)}</span><span>${esc(a.default_tier)}</span><span>${esc(a.max_iterations)} turns</span><span>${esc((a.allowed_tools||[]).length)} tools</span><span>${esc(a.required_approvals)} approvals</span></div></div>`).join('')||'<p>No agents.</p>';}
function renderTasks(items){$('taskCount').textContent=items.length;$('taskRows').innerHTML=items.map(t=>{let actions='';if(t.status==='waiting_approval')actions=`<button data-action="approve" data-id="${esc(t.id)}">Approve</button><button class="ghost" data-action="reject" data-id="${esc(t.id)}">Reject</button>`;else if(['queued','running'].includes(t.status))actions=`<button class="ghost" data-action="cancel" data-id="${esc(t.id)}">Cancel</button>`;else if(['failed','dead_letter'].includes(t.status))actions=`<button data-action="retry" data-id="${esc(t.id)}">Retry</button>`;return `<tr><td><span class="status ${esc(t.status)}">${esc(t.status)}</span></td><td>${esc(t.agent_id)}</td><td>${esc(t.tier)}<br><small>${esc(t.provider_name||'—')} / ${esc(t.model||'—')}</small></td><td>${fmt(t.cost_credits,5)}</td><td>${esc(t.outcome_status||'—')} ${t.outcome_score!=null?`(${fmt(t.outcome_score,2)})`:''}</td><td>${age(t.created_at)}</td><td><div class="actions">${actions}</div></td></tr>`;}).join('')||'<tr><td colspan="7">No tasks yet.</td></tr>';document.querySelectorAll('[data-action]').forEach(btn=>btn.addEventListener('click',()=>taskAction(btn.dataset.id,btn.dataset.action)));renderTimeline(items);}
function renderTimeline(tasks){const tl=$('activityTimeline');if(!tl)return;if(!tasks.length){tl.innerHTML='<div class="timeline-item"><div class="timeline-point bg-cyan"></div><div class="timeline-card"><span class="timeline-time">Just now</span><strong>zWorkforce Control Plane Online</strong><p>System ready for new task dispatches.</p></div></div>';return;}tl.innerHTML=tasks.slice(0,5).map(t=>{const color=t.status==='succeeded'?'bg-mint':(t.status==='failed'||t.status==='dead_letter'?'bg-danger':'bg-cyan');return `<div class="timeline-item"><div class="timeline-point ${color}"></div><div class="timeline-card"><span class="timeline-time">${age(t.created_at)}</span><strong>Task ${esc(t.id.slice(0,8))} · ${esc(t.agent_id)} (${esc(t.status)})</strong><p>Tier: ${esc(t.tier.toUpperCase())} · Model: ${esc(t.model||'auto')} · Cost: ${fmt(t.cost_credits,4)} credits</p></div></div>`;}).join('');}
function toggleCardFullscreen(cardId){const el=$(cardId);if(!el)return;el.classList.toggle('fullscreen-card');}
function renderMix(items){const total=items.reduce((s,x)=>s+Number(x.cost||0),0)||items.reduce((s,x)=>s+Number(x.turns||0),0)||1;$('mixList').innerHTML=items.map(x=>{const v=Number(x.cost||0)||Number(x.turns||0);const pct=Math.max(2,Math.round(v/total*100));return `<div class="bar-row"><strong>${esc(x.tier)}</strong><progress class="bar-progress" max="100" value="${pct}">${pct}%</progress><span>${fmt(x.cost,4)} cr</span></div>`;}).join('')||'<p>No usage yet.</p>';}
function renderProviders(items,mix){const turns=Object.fromEntries(mix.map(x=>[x.provider_name,x.turns]));$('providerHealth').innerHTML=items.map(p=>`<div class="provider"><div><strong>${esc(p.name)}</strong><small> · ${esc(p.kind)}</small></div><span class="status ${p.available?'succeeded':'failed'}">${p.available?'healthy':'circuit open'}</span></div>`).join('');$('providerList').innerHTML=items.map(p=>`<div class="provider"><div><strong>${esc(p.name)}</strong><small> priority ${esc(p.priority)}</small></div><span>${fmt(turns[p.name]||0,0)} turns</span></div>`).join('')||'<p>No provider data.</p>';}
function renderRecommendations(items){$('recommendations').innerHTML=items.map(r=>`<div class="rec"><strong>${esc(r.agent_id)} · ${esc(r.action)}</strong><p>${esc(r.from)} → ${esc(r.to)} · confidence ${esc(r.confidence)} · ${esc(JSON.stringify(r.evidence))}</p></div>`).join('')||'<div class="rec"><strong>No rightsizing signal yet</strong><p>Recommendations appear after enough evaluated task history exists.</p></div>';}
function renderMemories(items){$('memoryList').innerHTML=items.map(m=>`<div class="memory"><strong>${esc(m.title)}</strong><p>${esc((m.content||'').slice(0,220))}</p></div>`).join('')||'<p>No matching memory.</p>';}
async function taskAction(id,action){try{await api(`/api/v1/tasks/${id}/${action}`,{method:'POST',body:{comment:`Dashboard ${action}`}});await refresh();}catch(err){banner(err.message);}}
function clearDashboardPolling(){if(dashboardPollingTimer){clearInterval(dashboardPollingTimer);dashboardPollingTimer=null;}}
function startDashboardPolling(){if(dashboardPollingTimer||!state.key)return;dashboardPollingTimer=setInterval(()=>{if(state.key)void refresh();},5000);}
function scheduleDashboardRefresh(){if(dashboardRefreshTimer||!state.key)return;dashboardRefreshTimer=setTimeout(()=>{dashboardRefreshTimer=null;if(state.key)void refresh();},250);}
function handleDashboardRealtimeStatus(status){if(status==='POLLING'||status==='STALE')startDashboardPolling();else if(status==='LIVE'){if(!dashboardSnapshotStale)clearDashboardPolling();else startDashboardPolling();}else if(status==='OFFLINE')clearDashboardPolling();}
function destroyDashboardRealtime(){dashboardRealtimeGeneration+=1;dashboardRealtime?.destroy?.();dashboardRealtime=null;clearDashboardPolling();if(dashboardRefreshTimer){clearTimeout(dashboardRefreshTimer);dashboardRefreshTimer=null;}}
async function loadDashboardRealtime(){if(!state.key)return;const generation=dashboardRealtimeGeneration;if(dashboardRealtime){dashboardRealtime.restart();return;}if(!dashboardRealtimeLoad){dashboardRealtimeLoad=import('/dashboard/bootstrap.js').then(({createDashboardRealtime})=>{if(generation!==dashboardRealtimeGeneration||!state.key)return;dashboardRealtime=createDashboardRealtime({root:document,getSession:()=>({key:state.key,tenant:state.tenant}),onEvent:(event)=>{if(event?.event!=='heartbeat')scheduleDashboardRefresh();},onStatus:handleDashboardRealtimeStatus});if(generation===dashboardRealtimeGeneration)dashboardRealtime.start();}).catch(()=>{if(generation===dashboardRealtimeGeneration&&state.key)handleDashboardRealtimeStatus('STALE');}).finally(()=>{dashboardRealtimeLoad=null;if(state.key&&generation!==dashboardRealtimeGeneration&&!dashboardRealtime)void loadDashboardRealtime();});}await dashboardRealtimeLoad;}
function restartDashboardRealtime(){if(!state.key){destroyDashboardRealtime();return;}void loadDashboardRealtime();}
$('connectBtn').addEventListener('click',()=>{void stopZarvisVoiceTransport();state.key=$('apiKey').value.trim();state.tenant=$('tenantId').value.trim()||'default';sessionStorage.setItem('zwf:key',state.key);sessionStorage.setItem('zwf:tenant',state.tenant);void refresh();restartDashboardRealtime();});
$('refreshBtn').addEventListener('click',refresh);
function toggleControlSidebar(open){const sb=$('controlSidebar');const ob=$('controlSidebarOverlay');if(!sb)return;const shouldOpen=open!==undefined?open:sb.classList.contains('hidden');sb.classList.toggle('hidden',!shouldOpen);ob?.classList.toggle('hidden',!shouldOpen);}
$('controlSidebarBtn')?.addEventListener('click',()=>toggleControlSidebar());
$('closeControlSidebar')?.addEventListener('click',()=>toggleControlSidebar(false));
$('controlSidebarOverlay')?.addEventListener('click',()=>toggleControlSidebar(false));
window.addEventListener('keydown',(e)=>{if(e.key==='Escape'&&!$('controlSidebar')?.classList.contains('hidden'))toggleControlSidebar(false);});
$('sidebarRefreshHealthBtn')?.addEventListener('click',async()=>{banner('');await refresh();});
$('sidebarPurgeVoiceBtn')?.addEventListener('click',async()=>{await stopZarvisVoiceTransport();await refreshZarvisVoiceHealth();});
$('prometaInstallBtn').addEventListener('click',async()=>{try{const btn=$('prometaInstallBtn');btn.disabled=true;$('prometaStatus').textContent='Installing ProMeta baseline...';const data=await api('/api/v1/prometa/install',{method:'POST',body:{}});$('prometaStatus').textContent=`Installed ${data.agents} agents, ${data.skills} skills, ${data.agent_templates} templates and ${data.workflows} workflows.`;await refresh();}catch(err){banner(err.message);$('prometaStatus').textContent='ProMeta install failed.';}finally{$('prometaInstallBtn').disabled=false;}});

let slashActiveIndex = -1;
let slashFiltered = [];
function updateSlashMenu(){const menu=$('slashMenu');const hint=$('slashHint');if(!menu)return;const val=$('prompt').value;if(!val.startsWith('/')){menu.classList.add('hidden');if(hint)hint.classList.add('hidden');slashFiltered=[];slashActiveIndex=-1;return;}const query=val.slice(1).split(/\s+/)[0].toLowerCase();slashFiltered=state.commands.filter(c=>c.name.toLowerCase().startsWith(query));if(!slashFiltered.length){menu.classList.add('hidden');slashActiveIndex=-1;return;}if(slashActiveIndex<0||slashActiveIndex>=slashFiltered.length)slashActiveIndex=0;menu.innerHTML=slashFiltered.map((c,i)=>`<div class="slash-item ${i===slashActiveIndex?'active':''}" data-index="${i}"><strong>/${esc(c.name)}</strong><span>${esc(c.description)}</span><small>${esc(c.target||c.scope)}</small></div>`).join('');menu.classList.remove('hidden');menu.querySelectorAll('.slash-item').forEach(el=>el.addEventListener('click',()=>{selectSlashCommand(Number(el.dataset.index));}));if(hint){const activeCmd=slashFiltered[slashActiveIndex];if(activeCmd){hint.textContent=`/${activeCmd.name}: ${activeCmd.description}`;hint.classList.remove('hidden');}}}
function selectSlashCommand(index){if(index<0||index>=slashFiltered.length)return;const cmd=slashFiltered[index];const promptEl=$('prompt');const rest=promptEl.value.replace(/^\/[a-zA-Z0-9_-]*/,'').trimStart();promptEl.value=`/${cmd.name}${rest?' '+rest:' '}`;promptEl.focus();$('slashMenu').classList.add('hidden');if($('slashHint'))$('slashHint').classList.add('hidden');slashActiveIndex=-1;}
$('prompt').addEventListener('input',updateSlashMenu);
$('prompt').addEventListener('keydown',(e)=>{const menu=$('slashMenu');if(menu.classList.contains('hidden')||!slashFiltered.length)return;if(e.key==='ArrowDown'){e.preventDefault();slashActiveIndex=(slashActiveIndex+1)%slashFiltered.length;updateSlashMenu();}else if(e.key==='ArrowUp'){e.preventDefault();slashActiveIndex=(slashActiveIndex-1+slashFiltered.length)%slashFiltered.length;updateSlashMenu();}else if(e.key==='Enter'||e.key==='Tab'){if(!e.shiftKey&&slashActiveIndex>=0){e.preventDefault();selectSlashCommand(slashActiveIndex);}}else if(e.key==='Escape'){menu.classList.add('hidden');if($('slashHint'))$('slashHint').classList.add('hidden');}});
document.addEventListener('click',(e)=>{if(!e.target.closest('.prompt-wrap')){$('slashMenu')?.classList.add('hidden');$('slashHint')?.classList.add('hidden');}});

$('dispatchForm').addEventListener('submit',async(e)=>{e.preventDefault();try{let promptText=$('prompt').value.trim();if(promptText.startsWith('/')){try{const res=await api('/api/v1/workspaces/commands/resolve',{method:'POST',body:{text:promptText}});if(res&&res.resolved){promptText=`[command:${res.target}] ${res.argument||''}`.trim();}}catch(err){banner(`Slash command resolution error: ${err.message}`);return;}}const body={agent_id:$('agentSelect').value,prompt:promptText,mutating:$('mutating').checked,priority:Number($('priority').value||0)};if($('tierSelect').value)body.tier_override=$('tierSelect').value;await api('/api/v1/tasks',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body});$('prompt').value='';$('slashMenu')?.classList.add('hidden');$('slashHint')?.classList.add('hidden');await refresh();}catch(err){banner(err.message);}});
$('memoryForm').addEventListener('submit',async(e)=>{e.preventDefault();try{const q=encodeURIComponent($('memoryQuery').value.trim());const data=await api(`/api/v1/memories?limit=20${q?`&q=${q}`:''}`);renderMemories(data.items||[]);}catch(err){banner(err.message);}});

