async campaigns(){const d=await api('/api/v1/kids/campaigns');$('kidsStudioBody').innerHTML=`<div class="studio-form"><h3>New campaign</h3>${kidsStudioInput('ksCampId','ID (slug)','colors-q1')}${kidsStudioInput('ksCampBrand','Brand ID','lumikids')}${kidsStudioInput('ksCampName','Name','Colors Q1')}${kidsStudioInput('ksCampTopic','Topic','five colors')}<button id="ksCampCreate">Create / update</button></div><div id="ksCampList"></div>`;$('ksCampList').innerHTML=kidsStudioTable(['ID','Name','Brand','Topic','Status'],(d.items||[]).map(c=>[esc(c.id),esc(c.name),esc(c.brand_id),esc(c.topic||'—'),esc(c.status||'planned')]));$('ksCampCreate').addEventListener('click',async()=>{try{await kidsStudioUpsert('/api/v1/kids/campaigns',kidsStudioField('ksCampId'),{id:kidsStudioField('ksCampId'),brand_id:kidsStudioField('ksCampBrand'),name:kidsStudioField('ksCampName'),topic:kidsStudioField('ksCampTopic')});kidsStudioSetStatus('Campaign saved (untouched fields preserved).');await kidsStudioShow('campaigns');}catch(err){kidsStudioSetStatus(`Save failed: ${err.message}`);}});},
