async scripts(){const eps=await api('/api/v1/kids/episodes?limit=100');const first=((eps.items||[])[0]||{}).id||'';let script=null;if(first){try{script=await api(`/api/v1/kids/episodes/${encodeURIComponent(first)}/script`);}catch{script=null;}}$('kidsStudioBody').innerHTML=`<div class="studio-form"><h3>Save script version</h3>${kidsStudioInput('ksScriptEp','Episode ID',first,first)}${kidsStudioInput('ksScriptVerses','Verses','Red bus, blue sky')}${kidsStudioInput('ksScriptChorus','Chorus','Colors we love')}<button id="ksScriptSave">Save version</button></div><div id="ksScriptView"></div>`;$('ksScriptView').innerHTML=script&&script.version?`<p>Latest v${esc(script.version)} (${esc(script.content_type||'')})</p><pre>${esc(JSON.stringify(script.body||{},null,2).slice(0,1200))}</pre>`:'<p>No script yet for the selected episode.</p>';$('ksScriptSave').addEventListener('click',async()=>{try{await kidsStudioPost(`/api/v1/kids/episodes/${encodeURIComponent(kidsStudioField('ksScriptEp'))}/script`,{content_type:'nursery_rhyme',body:{verses:kidsStudioField('ksScriptVerses'),chorus:kidsStudioField('ksScriptChorus')}});kidsStudioSetStatus('Script version saved.');await kidsStudioShow('scripts');}catch(err){kidsStudioSetStatus(`Save failed: ${err.message}`);}});},
