async renders(){const d=await api('/api/v1/kids/render-jobs');$('kidsStudioBody').innerHTML=`<div class="studio-form"><h3>Render worker</h3><button id="ksTick">Tick once</button> <button id="ksTickAll">Tick all (5)</button></div><div id="ksRenderList"></div>`;$('ksRenderList').innerHTML=kidsStudioTable(['Job','Episode','Preset','Status','SHA-256','Attempts'],(d.items||[]).slice(0,30).map(j=>[esc((j.id||'').slice(0,8)),esc(j.episode_id),esc(j.preset),esc(j.status),esc((j.output_sha256||'').slice(0,12)),esc(j.attempts??0)]));$('ksTick').addEventListener('click',async()=>{try{const r=await kidsStudioPost('/api/v1/kids/render-jobs/tick',{});kidsStudioSetStatus(r.processed?`Ticked: ${(r.render_job||{}).status}`:'Queue empty.');await kidsStudioShow('renders');}catch(err){kidsStudioSetStatus(`Tick failed: ${err.message}`);}});$('ksTickAll').addEventListener('click',async()=>{try{const r=await kidsStudioPost('/api/v1/kids/render-jobs/tick-all',{limit:5});kidsStudioSetStatus(`Tick-all: ${r.processed} processed, idle=${r.idle}${r.drained===undefined?'':`, drained=${r.drained}`}.`);await kidsStudioShow('renders');}catch(err){kidsStudioSetStatus(`Tick-all failed: ${err.message}`);}});},
async approvals(){const d=await api('/api/v1/kids/approvals?state=pending');$('kidsStudioBody').innerHTML=kidsStudioTable(['ID','Episode','Subject','Version','Requested by','Actions'],(d.items||[]).map(a=>[esc((a.id||'').slice(0,8)),esc(a.episode_id),esc(`${a.subject_type}:${a.subject_id}`),esc(a.subject_version),esc(a.created_by),`<button data-approve="${esc(a.id)}">Approve</button> <button data-reject="${esc(a.id)}">Reject</button>`]));document.querySelectorAll('[data-approve]').forEach(b=>b.addEventListener('click',async()=>{try{await kidsStudioPost(`/api/v1/kids/approvals/${encodeURIComponent(b.dataset.approve)}/approve`,{comment:'Studio approval'});kidsStudioSetStatus('Approved (four-eyes enforced: requester cannot approve own).');await kidsStudioShow('approvals');}catch(err){kidsStudioSetStatus(`Approve failed: ${err.message}`);}}));document.querySelectorAll('[data-reject]').forEach(b=>b.addEventListener('click',async()=>{try{await kidsStudioPost(`/api/v1/kids/approvals/${encodeURIComponent(b.dataset.reject)}/reject`,{comment:'Studio rejection'});kidsStudioSetStatus('Rejected.');await kidsStudioShow('approvals');}catch(err){kidsStudioSetStatus(`Reject failed: ${err.message}`);}}));if(!(d.items||[]).length)kidsStudioSetStatus('Approval queue empty.');},
async schedules(){const d=await api('/api/v1/kids/schedules');$('kidsStudioBody').innerHTML=`<div class="studio-form"><h3>New slot (future ISO + timezone)</h3>${kidsStudioInput('ksSchedChan','Channel ID','lumikids-rhymes')}${kidsStudioInput('ksSchedEp','Episode ID','color-bus')}${kidsStudioInput('ksSchedSlot','Slot (ISO)','2030-05-01T09:00:00+07:00')}<button id="ksSchedCreate">Schedule</button></div><div id="ksSchedList"></div>`;$('ksSchedList').innerHTML=kidsStudioTable(['ID','Channel','Episode','Slot','Status','Actions'],(d.items||[]).map(s=>[esc((s.id||'').slice(0,8)),esc(s.channel_id),esc(s.episode_id),esc(s.slot_at),esc(s.status),s.status==='scheduled'?`<button data-cancel-sched="${esc(s.id)}">Cancel</button>`:'—']));$('ksSchedCreate').addEventListener('click',async()=>{try{await kidsStudioPost('/api/v1/kids/schedules',{channel_id:kidsStudioField('ksSchedChan'),episode_id:kidsStudioField('ksSchedEp'),slot_at:kidsStudioField('ksSchedSlot')},{'Idempotency-Key':crypto.randomUUID()});kidsStudioSetStatus('Slot scheduled.');await kidsStudioShow('schedules');}catch(err){kidsStudioSetStatus(`Schedule failed: ${err.message}`);}});document.querySelectorAll('[data-cancel-sched]').forEach(b=>b.addEventListener('click',async()=>{try{await kidsStudioPost(`/api/v1/kids/schedules/${encodeURIComponent(b.dataset.cancelSched)}/cancel`,{});kidsStudioSetStatus('Slot canceled.');await kidsStudioShow('schedules');}catch(err){kidsStudioSetStatus(`Cancel failed: ${err.message}`);}}));},
async analytics(){const s=await api('/api/v1/kids/analytics/summary');$('kidsStudioBody').innerHTML=kidsStudioTable(['Group','Detail'],[...Object.entries(s.episodes_by_status||{}).map(([k,v])=>[`Episodes: ${esc(k)}`,esc(v)]),...Object.entries(s.renders_by_status||{}).map(([k,v])=>[`Renders: ${esc(k)}`,esc(v)]),...Object.entries(s.approvals_by_state||{}).map(([k,v])=>[`Approvals: ${esc(k)}`,esc(v)]),['Usage cost',fmt((s.usage||{}).cost_credits,4)],['Synthetic snapshots',esc((s.analytics_snapshots||{}).synthetic??0)]]);kidsStudioSetStatus('Aggregated from persisted rows only; forecasts are estimates.');},
async providers(){const d=await api('/api/v1/kids/providers/routes');const known=await api('/api/v1/kids/providers');$('kidsStudioBody').innerHTML=`<div class="studio-form"><h3>Set route (ordered providers)</h3>${kidsStudioInput('ksRouteCap','Capability (llm/image/video/tts/music)','image')}${kidsStudioInput('ksRouteProviders','Providers (comma)','mock')}<button id="ksRouteSet">Set route</button></div><div id="ksRouteList"></div><div id="ksKnownList"></div>`;$('ksRouteList').innerHTML=kidsStudioTable(['Capability','Route (enabled flags)'],(d.items||[]).map(r=>[esc(r.capability),esc((r.providers||[]).join(' → '))]));$('ksKnownList').innerHTML=kidsStudioTable(['Capability','Provider','Mode','Enabled'],(known.items||[]).map(p=>[esc(p.capability),esc(p.provider),esc(p.mode),esc(p.enabled?'yes':'no')]));$('ksRouteSet').addEventListener('click',async()=>{try{await kidsStudioPost('/api/v1/kids/providers/routes',{capability:kidsStudioField('ksRouteCap'),providers:kidsStudioField('ksRouteProviders').split(',').map(x=>x.trim()).filter(Boolean)});kidsStudioSetStatus('Route saved (externals stay disabled until configured).');await kidsStudioShow('providers');}catch(err){kidsStudioSetStatus(`Route failed: ${err.message}`);}});},
