const zeazverseStudio={tab:'overview'};
function zvStatus(message){const el=$('zeazverseStudioStatus');if(el)el.textContent=message;}
function zvField(id){return kidsStudioField(id);}
function zvEpisodesOptions(items,selected=''){return (items||[]).map(e=>`<option value="${esc(e.id)}"${e.id===selected?' selected':''}>${esc(e.title||e.id)} (${esc(e.status)})</option>`).join('');}
async function zvLoadEpisodes(){return (await api('/api/v1/zeazverse/episodes?limit=100')).episodes||[];}
async function zeazverseShow(tab){
  zeazverseStudio.tab=tab||'overview';
  document.querySelectorAll('[data-zv-tab]').forEach(b=>b.classList.toggle('active',b.dataset.zvTab===zeazverseStudio.tab));
  const body=$('zeazverseStudioBody');if(!body)return;
  if(!state.key){body.innerHTML='<p>Connect to load ZEAZVERSE tenant data.</p>';return;}
  body.innerHTML='<p>Loading ZEAZVERSE data…</p>';
  try{await zeazverseScreens[zeazverseStudio.tab]();}
  catch(err){body.innerHTML=`<p>Failed to load: ${esc(err.message)}</p>`;zvStatus(`ZEAZVERSE error: ${err.message}`);}
}
document.querySelectorAll('[data-zv-tab]').forEach(b=>b.addEventListener('click',()=>void zeazverseShow(b.dataset.zvTab)));
const zeazverseScreens={
  async overview(){const [brand,chars,series,episodes,approvals]=await Promise.all([api('/api/v1/zeazverse/brand'),api('/api/v1/zeazverse/characters'),api('/api/v1/zeazverse/series'),zvLoadEpisodes(),api('/api/v1/zeazverse/approvals?state=pending')]);$('zeazverseStudioBody').innerHTML=`<div class="card-grid">${[['Brand',brand.brand.name],['Characters',(chars.characters||[]).length],['Series',(series.series||[]).length],['Episodes',episodes.length],['Pending approvals',(approvals.approvals||[]).length]].map(([k,v])=>`<div class="card"><h3>${esc(k)}</h3><p>${esc(v)}</p></div>`).join('')}</div><p>${esc(brand.brand.tagline)} · Private-first publishing · Human visual QA required</p>`;zvStatus('Live tenant state loaded. Synthetic storyboard samples are not generated character footage.');},
  async channel(){const d=await api('/api/v1/zeazverse/channel');const steps=d.all_steps||[];$('zeazverseStudioBody').innerHTML=`<div class="studio-form"><h3>Channel setup checklist</h3><p>Mark a step only after completing it in the owning YouTube account.</p>${steps.map(s=>{const v=(d.checklist||{})[s.id]||{};return `<div class="studio-field"><span>${esc(s.name||s.title||s.label||s.id)} — ${esc(v.status||'pending')}</span><button data-zv-step="${esc(s.id)}">Mark requires user action</button> <button data-zv-step-done="${esc(s.id)}">Mark verified</button></div>`;}).join('')}</div><pre>${esc(JSON.stringify(d.channel,null,2))}</pre>`;document.querySelectorAll('[data-zv-step]').forEach(b=>b.addEventListener('click',()=>void zvSetupStep(b.dataset.zvStep,'requires_user_action')));document.querySelectorAll('[data-zv-step-done]').forEach(b=>b.addEventListener('click',()=>void zvSetupStep(b.dataset.zvStepDone,'verified')));zvStatus('Checklist state is saved per tenant; account actions remain operator-controlled.');},
  async characters(){const d=await api('/api/v1/zeazverse/characters');$('zeazverseStudioBody').innerHTML=kidsStudioTable(['ID','Name','Age','Nationality','Archetype','Bible'],(d.characters||[]).map(c=>[esc(c.id),esc(c.name),esc(c.age),esc(c.nationality),esc(c.archetype),`<details><summary>View</summary><pre>${esc(JSON.stringify({appearance:c.appearance,personality:c.personality,story_themes:c.story_themes},null,2))}</pre></details>`]));zvStatus('Canonical Character Bibles loaded from tenant-scoped storage.');},
  async series(){const [s,episodes]=await Promise.all([api('/api/v1/zeazverse/series'),zvLoadEpisodes()]);$('zeazverseStudioBody').innerHTML=`<div class="studio-form"><h3>Create series</h3>${kidsStudioInput('zvSeriesId','Series ID','cyber-bangkok')}${kidsStudioInput('zvSeriesTitle','Title','Cyber Bangkok 2088')}${kidsStudioInput('zvSeriesClass','Content class','Cyberpunk Stories')}${kidsStudioInput('zvSeriesSynopsis','Synopsis','A science fiction series set in Bangkok.')}<button id="zvCreateSeries">Create series</button></div><div class="studio-form"><h3>Create episode</h3>${kidsStudioInput('zvEpId','Episode ID','pilot-01')}${kidsStudioInput('zvEpSeries','Series ID',(s.series||[])[0]?.id||'')}${kidsStudioInput('zvEpTitle','Title','Awakening of LALIN')}${kidsStudioInput('zvEpClass','Content class','Cyberpunk Stories')}${kidsStudioInput('zvEpCharacters','Character IDs (comma)','lalin')}<button id="zvCreateEpisode">Create episode</button></div><div id="zvEpisodesList"></div>`;$('zvEpisodesList').innerHTML=kidsStudioTable(['ID','Title','Series','Status'],episodes.map(e=>[esc(e.id),esc(e.title),esc(e.series_id),esc(e.status)]));$('zvCreateSeries').addEventListener('click',async()=>{try{await kidsStudioPost('/api/v1/zeazverse/series',{id:zvField('zvSeriesId'),title:zvField('zvSeriesTitle'),content_class:zvField('zvSeriesClass'),synopsis:zvField('zvSeriesSynopsis')});zvStatus('Series created.');await zeazverseShow('series');}catch(err){zvStatus(`Create series failed: ${err.message}`);}});$('zvCreateEpisode').addEventListener('click',async()=>{try{await kidsStudioPost('/api/v1/zeazverse/episodes',{id:zvField('zvEpId'),series_id:zvField('zvEpSeries'),title:zvField('zvEpTitle'),content_class:zvField('zvEpClass'),characters:zvField('zvEpCharacters').split(',').map(x=>x.trim()).filter(Boolean)},{'Idempotency-Key':crypto.randomUUID()});zvStatus('Episode created.');await zeazverseShow('series');}catch(err){zvStatus(`Create episode failed: ${err.message}`);}});},
  async storyboard(){const episodes=await zvLoadEpisodes();$('zeazverseStudioBody').innerHTML=`<div class="studio-form"><h3>Storyboard and metadata</h3><label class="studio-field"><span>Episode</span><select id="zvStoryboardEpisode">${zvEpisodesOptions(episodes)}</select></label><button id="zvGenerateStoryboard">Generate storyboard</button> <button id="zvGenerateSeo">Generate SEO metadata</button></div><div id="zvScenesList"></div>`;const load=async()=>{const id=zvField('zvStoryboardEpisode');if(!id)return;$('zvScenesList').innerHTML=kidsStudioTable(['Order','Scene','Time','Action','Dialogue'],((await api(`/api/v1/zeazverse/episodes/${encodeURIComponent(id)}/scenes`)).scenes||[]).map(s=>[esc(s.ordering),esc(s.id),`${esc(s.time_start_seconds)}–${esc(s.time_end_seconds)}s`,esc(s.subject_action),esc(s.dialogue?.text_en||'—')]));};$('zvGenerateStoryboard').addEventListener('click',async()=>{try{const id=zvField('zvStoryboardEpisode');await kidsStudioPost(`/api/v1/zeazverse/episodes/${encodeURIComponent(id)}/generate-storyboard`,{});await load();zvStatus('Storyboard generated; inspect scene prompts and continuity before rendering.');}catch(err){zvStatus(`Storyboard failed: ${err.message}`);}});$('zvGenerateSeo').addEventListener('click',async()=>{try{const id=zvField('zvStoryboardEpisode');await kidsStudioPost(`/api/v1/zeazverse/episodes/${encodeURIComponent(id)}/generate-seo`,{});zvStatus('Private-first SEO metadata generated.');}catch(err){zvStatus(`SEO generation failed: ${err.message}`);}});await load();},
  async render(){const episodes=await zvLoadEpisodes();$('zeazverseStudioBody').innerHTML=`<div class="studio-form"><h3>Render and human visual QA</h3><label class="studio-field"><span>Episode</span><select id="zvRenderEpisode">${zvEpisodesOptions(episodes)}</select></label><button id="zvRender">Render abstract sample</button><div id="zvRenderPreview"></div></div>`;const id=()=>zvField('zvRenderEpisode');$('zvRender').addEventListener('click',async()=>{try{const r=await kidsStudioPost(`/api/v1/zeazverse/episodes/${encodeURIComponent(id())}/render`,{});const artifact=r.render_result?.video_artifact;$('zvRenderPreview').innerHTML=`<p>Rendered ${esc(r.render_result?.render_kind)} · SHA-256 ${esc(r.render_result?.output_sha256)}</p><p>This sample uses abstract cards and silence. Review the video below; it is not final idol footage.</p>${artifact?.id?'<p>Loading secured preview…</p>':''}`;if(artifact?.id){const file=await api(`/api/v1/artifacts/${encodeURIComponent(artifact.id)}/content`);$('zvRenderPreview').insertAdjacentHTML('beforeend',`<video controls playsinline style="max-width:100%;max-height:60vh" src="data:${esc(file.content_type)};base64,${file.content_base64}"></video><div><button id="zvQaPass">Visual QA passed</button> <button id="zvQaFail">Visual QA failed</button></div>`);$('zvQaPass').addEventListener('click',()=>void zvQa(true));$('zvQaFail').addEventListener('click',()=>void zvQa(false));}zvStatus(`Render state: ${r.status}. Encoder checks passed; visual approval is still pending.`);}catch(err){zvStatus(`Render failed: ${err.message}`);}});async function zvQa(passed){try{await kidsStudioPost(`/api/v1/zeazverse/episodes/${encodeURIComponent(id())}/qa-review`,{visual_review_passed:passed,notes:passed?'Human visual review passed.':'Human visual review failed.'});zvStatus(passed?'Human visual QA passed. An independent publishing approval is still required.':'Visual QA failed; episode cannot be approved.');}catch(err){zvStatus(`QA review failed: ${err.message}`);}}},
  async publishing(){const [episodes,pending,approved]=await Promise.all([zvLoadEpisodes(),api('/api/v1/zeazverse/approvals?state=pending'),api('/api/v1/zeazverse/approvals?state=approved')]);$('zeazverseStudioBody').innerHTML=`<div class="studio-form"><h3>Request approval after human QA</h3><label class="studio-field"><span>Episode</span><select id="zvApprovalEpisode">${zvEpisodesOptions(episodes.filter(e=>e.status==='QA_PASSED'))}</select></label><label class="studio-field"><span>Visibility</span><select id="zvVisibility"><option>private</option><option>unlisted</option><option>public</option></select></label><button id="zvRequestApproval">Request approval</button></div><h3>Pending approval (another reviewer must decide)</h3><div id="zvPendingApprovals"></div><h3>Approved; provider unavailable until YouTube OAuth integration is configured</h3><div id="zvApprovedApprovals"></div>`;const list=(items,buttons)=>kidsStudioTable(['Request','Episode','Visibility','Requester','Actions'],(items||[]).map(a=>[esc(a.id),esc(a.episode_id),esc(a.target_visibility),esc(a.created_by),buttons(a)]));$('zvPendingApprovals').innerHTML=list(pending.approvals,a=>`<button data-zv-approve="${esc(a.id)}">Approve</button> <button data-zv-reject="${esc(a.id)}">Reject</button>`);$('zvApprovedApprovals').innerHTML=list(approved.approvals,a=>`<button data-zv-publish="${esc(a.episode_id)}" data-zv-approval="${esc(a.id)}">Attempt publish</button>`);$('zvRequestApproval').addEventListener('click',async()=>{try{await kidsStudioPost(`/api/v1/zeazverse/episodes/${encodeURIComponent(zvField('zvApprovalEpisode'))}/request-approval`,{target_visibility:zvField('zvVisibility')},{'Idempotency-Key':crypto.randomUUID()});zvStatus('Approval requested. The requester cannot approve their own request.');await zeazverseShow('publishing');}catch(err){zvStatus(`Approval request failed: ${err.message}`);}});document.querySelectorAll('[data-zv-approve],[data-zv-reject]').forEach(b=>b.addEventListener('click',async()=>{try{await kidsStudioPost('/api/v1/zeazverse/approvals/decide',{request_id:b.dataset.zvApprove||b.dataset.zvReject,approved:b.hasAttribute('data-zv-approve'),comment:'Independent human review'});zvStatus('Approval decision recorded.');await zeazverseShow('publishing');}catch(err){zvStatus(`Decision failed: ${err.message}`);}}));document.querySelectorAll('[data-zv-publish]').forEach(b=>b.addEventListener('click',async()=>{try{await kidsStudioPost(`/api/v1/zeazverse/episodes/${encodeURIComponent(b.dataset.zvPublish)}/publish`,{approval_id:b.dataset.zvApproval});}catch(err){zvStatus(`Publish not completed: ${err.message}. Approval remains unconsumed until YouTube provider setup.`);}}));zvStatus('Private-first workflow. Approval is independent; real YouTube publishing is not configured.');}
};
async function zvSetupStep(stepId,status){try{await kidsStudioPost('/api/v1/zeazverse/channel/setup-step',{step_id:stepId,status});zvStatus(`Channel checklist updated: ${stepId} → ${status}.`);await zeazverseShow('channel');}catch(err){zvStatus(`Checklist update failed: ${err.message}`);}}

